import { TaskStatus } from './TaskStatus';

export abstract class Task {
  abstract id: string;
  abstract projectId: string;
  abstract title: string;
  abstract description: string;
  abstract dueDate: string | null;
  abstract status: TaskStatus;
  abstract assignedToUserId: string | null;

  abstract markDone(): void;
  abstract assignToUser(userId: string): void;
}

export class TaskEntity extends Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: string | null;
  status: TaskStatus;
  assignedToUserId: string | null;

  constructor(
    id: string,
    projectId: string,
    title: string,
    description: string,
    dueDate: string | null,
    status: TaskStatus,
    assignedToUserId: string | null = null,
  ) {
    super();
    this.id = id;
    this.projectId = projectId;
    this.title = title;
    this.description = description;
    this.dueDate = dueDate;
    this.status = status;
    this.assignedToUserId = assignedToUserId;
  }

  markDone(): void {
    if (this.status === 'done') {
      throw new Error('Task is already marked as done');
    }
    this.status = 'done';
  }

  assignToUser(userId: string): void {
    this.assignedToUserId = userId;
  }
}

=====SOURCE-END=====

